# ============================================================================
# Architecture / 架构 / アーキテクチャ
# Shared runtime services: skill discovery, provider bridging, and local guides.
# 共享运行时服务：skill 发现、provider 桥接与本地指南。
# 共通ランタイムサービス：skill 発見、provider ブリッジ、ローカルガイド。
# ============================================================================

class SkillStore:
    def __init__(self, skills_root: Path):
        self.skills_root = skills_root
        self.skills: dict[str, dict] = {}
        self.aliases: dict[str, str] = {}
        self.ambiguous: dict[str, list[str]] = {}
        self.providers: dict[str, dict] = {}
        self.warnings: list[str] = []
        self.fingerprint = ""
        self.last_reload_ts = 0.0
        self.reload(force=True)

    def _sanitize_provider_id(self, raw: str, fallback: str) -> str:
        pid = re.sub(r"[^A-Za-z0-9._-]+", "-", (raw or "").strip().lower()).strip("-")
        return pid or fallback

    def _provider_exists(self, provider_id: str) -> bool:
        return provider_id in self.providers

    def _skill_meta_section(self, meta: dict, key: str) -> dict:
        section = meta.get(key) if isinstance(meta, dict) else {}
        return section if isinstance(section, dict) else {}

    def _skill_aliases(self, meta: dict) -> list[str]:
        aliases = _meta_string_list(meta.get("aliases"))
        aliases.extend(_meta_string_list(meta.get("alias")))
        cc = self._skill_meta_section(meta, "clouds_coder")
        aliases.extend(_meta_string_list(cc.get("aliases")))
        seen: set[str] = set()
        out: list[str] = []
        for item in aliases:
            key = item.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(item)
        return out

    def _skill_triggers(self, meta: dict) -> list[str]:
        triggers = _meta_string_list(meta.get("triggers"))
        cc = self._skill_meta_section(meta, "clouds_coder")
        triggers.extend(_meta_string_list(cc.get("triggers")))
        # Minimax nested metadata support
        mm = self._skill_meta_section(meta, "metadata")
        triggers.extend(_meta_string_list(mm.get("triggers")))
        # Extract only positive trigger keywords from description.  Older
        # versions accidentally treated the ``DO NOT TRIGGER`` clause as a
        # positive trigger, which made generic prose select unrelated skills.
        if not triggers:
            desc = str(meta.get("description", "") or "").strip()
            triggers.extend(self._extract_triggers_from_description(desc))
        seen: set[str] = set()
        out: list[str] = []
        for item in triggers:
            key = item.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(item)
        return out

    def _skill_negative_triggers(self, meta: dict) -> list[str]:
        """Return explicit exclusions without reading a skill body."""
        values: list[str] = []
        for key in ("negative_triggers", "negativeTriggers", "not_for", "notFor", "excludes", "exclude"):
            values.extend(_meta_string_list(meta.get(key)))
        cc = self._skill_meta_section(meta, "clouds_coder")
        for key in ("negative_triggers", "not_for", "excludes", "exclude"):
            values.extend(_meta_string_list(cc.get(key)))
        mm = self._skill_meta_section(meta, "metadata")
        for key in ("negative_triggers", "not_for", "excludes", "exclude"):
            values.extend(_meta_string_list(mm.get(key)))
        desc = str(meta.get("description", "") or "").strip()
        # Capture the clause after DO NOT TRIGGER until a sentence boundary.
        for match in re.finditer(
            r"DO\s+NOT\s+TRIGGER(?:\s+WHEN)?[:\s]+([^\n.]{3,500})",
            desc,
            re.IGNORECASE,
        ):
            segment = match.group(1).strip()
            quoted = [m.group(1) or m.group(2) for m in re.finditer(r"'([^']{2,60})'|\"([^\"]{2,60})\"", segment)]
            values.extend(quoted or [x.strip().strip("'\"") for x in re.split(r"[,;]", segment)])
        seen: set[str] = set()
        out: list[str] = []
        for value in values:
            item = str(value or "").strip()
            key = item.casefold()
            if not item or len(item) < 2 or key in seen:
                continue
            seen.add(key)
            out.append(item)
        return out[:24]

    def _skill_category(self, meta: dict) -> str:
        cc = self._skill_meta_section(meta, "clouds_coder")
        nested = self._skill_meta_section(meta, "metadata")
        return str(
            meta.get("category", cc.get("category", nested.get("category", ""))) or ""
        ).strip()

    def _skill_bool(self, meta: dict, key: str, default: bool = False) -> bool:
        cc = self._skill_meta_section(meta, "clouds_coder")
        nested = self._skill_meta_section(meta, "metadata")
        value = meta.get(key, cc.get(key, nested.get(key, default)))
        if isinstance(value, bool):
            return value
        return str(value or "").strip().lower() in {"1", "true", "yes", "on", "y"}

    def _skill_relation_list(self, meta: dict, key: str) -> list[str]:
        values = _meta_string_list(meta.get(key))
        cc = self._skill_meta_section(meta, "clouds_coder")
        values.extend(_meta_string_list(cc.get(key)))
        nested = self._skill_meta_section(meta, "metadata")
        values.extend(_meta_string_list(nested.get(key)))
        seen: set[str] = set()
        out: list[str] = []
        for value in values:
            item = str(value or "").strip()
            if item and item.casefold() not in seen:
                seen.add(item.casefold())
                out.append(item)
        return out[:24]

    def _skill_metadata_record(self, key: str, data: dict, *, score: float | None = None) -> dict:
        meta = dict(data.get("meta", {}) if isinstance(data.get("meta"), dict) else {})
        selection_meta = dict(meta)
        selection_meta.setdefault("description", str(data.get("description", "") or ""))
        infrastructure_only = self._skill_bool(selection_meta, "infrastructure_only", False) or bool(meta.get("builtin", False))
        row = {
            "id": str(key),
            "canonical_id": str(key),
            "name": str(data.get("name", key) or key),
            "qualified_name": str(key),
            "description": str(data.get("description", meta.get("description", "-")) or "-"),
            "provider_id": str(data.get("provider_id", "") or ""),
            "provider": str(data.get("provider_id", "") or ""),
            "protocol": str(data.get("protocol", "") or ""),
            "protocol_version": str(data.get("protocol_version", "") or ""),
            "meta": meta,
            "skill_path": data.get("skill_path", ""),
            "virtual_path": data.get("skill_path", ""),
            "attachments": [x.get("path", "") for x in data.get("attachments", []) if isinstance(x, dict)],
            "aliases": [n for n, sid in self.aliases.items() if sid == key],
            "triggers": self._skill_triggers(selection_meta),
            "negative_triggers": self._skill_negative_triggers(selection_meta),
            "keywords": self._skill_keywords(selection_meta),
            "category": self._skill_category(selection_meta),
            "entrypoints": self._skill_entrypoints(selection_meta),
            "preferred_tools": self._skill_relation_list(selection_meta, "preferred_tools"),
            "requires": self._skill_relation_list(selection_meta, "requires"),
            "conflicts": self._skill_relation_list(selection_meta, "conflicts"),
            "infrastructure_only": infrastructure_only,
        }
        if score is not None:
            row["score"] = round(float(score), 4)
        return row

    @staticmethod
    def _extract_triggers_from_description(desc: str) -> list[str]:
        """Extract trigger keywords from description text.

        Handles ALL skill ecosystems:
        - Minimax fullstack: "TRIGGER when: building a full-stack app, creating REST API..."
        - skills-main: "Triggers include: 'Word doc', 'word document', '.docx'..."
        - Kimi: Pure descriptive — "Excel文件操作（创建、验证、透视表）"
        - awesome-claude-skills: "Comprehensive PDF manipulation toolkit for..."
        - academic-pptx: "学术演讲内容和结构指南"
        """
        if not desc or len(desc) < 20:
            return []
        triggers: list[str] = []
        # Pattern 1: "TRIGGER when:" or "triggers include:" followed by comma list
        for m in re.finditer(r'(?:TRIGGER\s+when|triggers?\s+include)[:\s]+([^\n.]{10,600})', desc, re.IGNORECASE):
            segment = m.group(1).strip()
            # Extract quoted phrases
            for qm in re.finditer(r"'([^']{2,40})'|\"([^\"]{2,40})\"", segment):
                token = (qm.group(1) or qm.group(2) or "").strip()
                if token:
                    triggers.append(token)
            # Extract comma-separated items
            if not triggers:
                for item in re.split(r'[,;]', segment):
                    cleaned = item.strip().strip('"\'').strip()
                    if 3 <= len(cleaned) <= 50 and not cleaned.startswith("or "):
                        triggers.append(cleaned)
        # Pattern 2: "Use this skill when ... mentions of 'X', 'Y', 'Z'"
        for m in re.finditer(r"mention[s]?\s+of\s+([^\n.]{5,300})", desc, re.IGNORECASE):
            for qm in re.finditer(r"'([^']{2,40})'|\"([^\"]{2,40})\"", m.group(1)):
                token = (qm.group(1) or qm.group(2) or "").strip()
                if token:
                    triggers.append(token)
        # Pattern 3: "Use this skill when the user wants to <verb> <object>" — extract verb phrases
        for m in re.finditer(r'(?:use this skill|MUST use)[^.]*?(?:wants?\s+to|needs?\s+to|asks?\s+to)\s+([^.]{5,200})', desc, re.IGNORECASE):
            segment = m.group(1).strip()
            for item in re.split(r'[,;]|(?:\bor\b)', segment):
                cleaned = item.strip().strip('"\'').strip()
                if 3 <= len(cleaned) <= 60:
                    triggers.append(cleaned)
        # Pattern 4: Quoted terms anywhere — "make a PDF", "fill in the form", etc.
        if not triggers:
            for qm in re.finditer(r'"([^"]{3,40})"', desc):
                token = qm.group(1).strip()
                if token and not token.startswith("http"):
                    triggers.append(token)
        # Pattern 5: File extension mentions — .docx, .pdf, .xlsx, .pptx
        # Only match standalone extensions, not library names like "Paged.js" or "D3.js"
        for m in re.finditer(r'(?<![A-Za-z])\.(docx?|pdf|xlsx?|xls|pptx?|csv|tex|html?)\b', desc, re.IGNORECASE):
            ext = f".{m.group(1).lower()}"
            triggers.append(ext)
        # Pattern 6 (Kimi/generic fallback): Extract key terms from description
        if not triggers:
            # Use first 2 sentences for broader context
            sentences = re.split(r'(?<=[.!?])\s+', desc[:500])
            context = " ".join(sentences[:2]).strip() if sentences else desc[:300]
            # Chinese: extract terms
            cn_terms = re.findall(r'[\u4e00-\u9fff]{2,8}', context)
            triggers.extend(cn_terms[:5])
            # English: extract capitalized tech/domain terms
            tech_words = re.findall(r'\b([A-Z][a-zA-Z]{2,})\b', context)
            _GENERIC_CAPS = {"Use", "The", "This", "When", "For", "And", "But", "Not", "All",
                             "Any", "Has", "Are", "Was", "Can", "May", "Will", "Also", "Each",
                             "Professional", "Comprehensive", "Academic", "Supports", "Core",
                             "Create", "Process", "Includes", "Generate", "Suitable",
                             "Tools", "Specialized"}
            for w in tech_words:
                if w not in _GENERIC_CAPS:
                    triggers.append(w)
            # Extract compound terms: "full-stack", "track-changes"
            compound = re.findall(r'\b([a-zA-Z]+-[a-zA-Z]+)\b', context)
            triggers.extend(c for c in compound if len(c) >= 5)
            # Extract terms in parentheses: "(HTML+Paged.js)", "(read, extract, merge)"
            for m in re.finditer(r'\(([^)]{3,80})\)', desc[:500]):
                inner = m.group(1).strip()
                # Split by Chinese comma or +
                for part in re.split(r'[、+,/]', inner):
                    part = part.strip()
                    if 2 <= len(part) <= 30:
                        triggers.append(part)
        # Deduplicate while preserving order
        seen: set[str] = set()
        deduped: list[str] = []
        for t in triggers:
            low = t.lower()
            if low not in seen:
                seen.add(low)
                deduped.append(t)
        return deduped[:20]

    def _skill_keywords(self, meta: dict) -> list[str]:
        """Extract keywords from SKILL.md metadata for universal skill matching.

        Supports all three skill ecosystems:
        - Minimax: metadata.category, metadata.keywords, triggers array
        - skills-main: description-embedded triggers
        - awesome-claude-skills: description-embedded triggers
        """
        keywords = _meta_string_list(meta.get("keywords"))
        keywords.extend(_meta_string_list(meta.get("keyword")))
        cc = self._skill_meta_section(meta, "clouds_coder")
        keywords.extend(_meta_string_list(cc.get("keywords")))
        # Minimax nested metadata: extract category and sources as keywords
        mm = self._skill_meta_section(meta, "metadata")
        if mm:
            cat = str(mm.get("category", "") or "").strip()
            if cat:
                # "document-processing" → ["document-processing", "document", "processing"]
                keywords.append(cat)
                keywords.extend(cat.replace("-", " ").replace("_", " ").split())
            keywords.extend(_meta_string_list(mm.get("keywords")))
        # Also include runtime_compat tags
        keywords.extend(_meta_string_list(meta.get("runtime_compat")))
        seen: set[str] = set()
        out: list[str] = []
        for item in keywords:
            key = item.lower().strip()
            if key in seen or not key or len(key) < 2:
                continue
            seen.add(key)
            out.append(item)
        return out

    def _skill_entrypoints(self, meta: dict) -> list[str]:
        entrypoints = _meta_string_list(meta.get("entrypoints"))
        cc = self._skill_meta_section(meta, "clouds_coder")
        entrypoints.extend(_meta_string_list(cc.get("entrypoints")))
        out: list[str] = []
        seen: set[str] = set()
        for item in entrypoints:
            rel = str(PurePosixPath(str(item).replace("\\", "/"))).strip()
            if not rel or rel in {".", ".."}:
                continue
            if rel.startswith("/"):
                rel = rel.lstrip("/")
            if ".." in PurePosixPath(rel).parts:
                continue
            key = rel.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(rel)
        return out

    def _skill_runtime_contract(self, meta: dict) -> str:
        raw = meta.get("runtime_contract", "") if isinstance(meta, dict) else ""
        contract = raw.strip() if isinstance(raw, str) else ""
        cc = self._skill_meta_section(meta, "clouds_coder")
        if not contract:
            nested = cc.get("runtime_contract", "")
            contract = nested.strip() if isinstance(nested, str) else ""
        return "".join(ch for ch in contract.replace("\r\n", "\n").replace("\r", "\n") if ch in "\n\t" or ord(ch) >= 32)

    def _skill_attachment_globs(self, meta: dict) -> list[str]:
        globs = _meta_string_list(meta.get("attachments"))
        if not globs:
            globs = _meta_string_list(meta.get("resource_globs"))
        cc = self._skill_meta_section(meta, "clouds_coder")
        if not globs:
            globs = _meta_string_list(cc.get("attachments"))
        if not globs:
            globs = _meta_string_list(cc.get("resource_globs"))
        return globs

    def _register_alias(self, alias: str, key: str):
        alias_name = str(alias or "").strip()
        if not alias_name:
            return
        if alias_name in self.aliases:
            existing = self.aliases.pop(alias_name)
            items = self.ambiguous.setdefault(alias_name, [])
            if existing not in items:
                items.append(existing)
            if key not in items:
                items.append(key)
            return
        if alias_name in self.ambiguous:
            items = self.ambiguous.setdefault(alias_name, [])
            if key not in items:
                items.append(key)
            return
        self.aliases[alias_name] = key

    def _inline_skill_attachments(self, attachments: list[dict]) -> list[dict]:
        chosen: list[dict] = []
        total_chars = 0
        for item in sorted(
            attachments,
            key=lambda x: (
                -int(x.get("priority", 0) or 0),
                int(x.get("size", 0) or 0),
                str(x.get("path", "")).lower(),
            ),
        ):
            if not bool(item.get("text_available", False)):
                continue
            text = str(item.get("content", "") or "")
            if not text:
                continue
            if len(chosen) >= SKILL_INLINE_ATTACHMENT_MAX_FILES:
                continue
            if chosen and (total_chars + len(text)) > SKILL_INLINE_ATTACHMENT_MAX_CHARS:
                continue
            if (not chosen) and len(text) > SKILL_INLINE_ATTACHMENT_MAX_CHARS:
                continue
            chosen.append(item)
            total_chars += len(text)
        return chosen

    def _provider_root_path(self, provider_id: str) -> Path | None:
        row = self.providers.get(str(provider_id or "").strip(), {})
        raw = str(row.get("root", "") or "").strip() if isinstance(row, dict) else ""
        if not raw:
            return None
        try:
            return Path(raw).resolve()
        except Exception:
            return None

    def _provider_virtual_prefix(self, provider_id: str) -> str:
        pid = self._sanitize_provider_id(provider_id, "provider")
        return f"{SKILLS_VIRTUAL_PREFIX}/{SKILLS_EXTERNAL_MOUNT}/{pid}"

    def _public_provider_path(self, provider_id: str, raw_locator: str | Path) -> str:
        raw = str(raw_locator or "").strip()
        if not raw:
            return ""
        if raw == "(builtin)" or _is_http_url(raw):
            return raw
        base, sep, frag = raw.partition("#")
        if _is_http_url(base):
            return raw
        try:
            candidate = Path(base)
        except Exception:
            return self._public_skill_locator(raw)
        try:
            resolved = candidate.resolve() if candidate.is_absolute() else (self.skills_root / candidate).resolve()
        except Exception:
            resolved = None
        if resolved is not None:
            try:
                rel = resolved.relative_to(self.skills_root.resolve()).as_posix()
                public = SKILLS_VIRTUAL_PREFIX if rel in {"", "."} else f"{SKILLS_VIRTUAL_PREFIX}/{rel}"
                public = public.replace("//", "/")
                return public + (f"#{frag}" if sep else "")
            except Exception:
                pass
            root = self._provider_root_path(provider_id)
            if root is not None:
                try:
                    rel = resolved.relative_to(root).as_posix()
                    prefix = self._provider_virtual_prefix(provider_id)
                    public = prefix if rel in {"", "."} else f"{prefix}/{rel}"
                    public = public.replace("//", "/")
                    return public + (f"#{frag}" if sep else "")
                except Exception:
                    pass
        return self._public_skill_locator(raw)

    def resolve_virtual_skill_path(self, rel_path: str) -> Path:
        rel = str(PurePosixPath(str(rel_path or "").replace("\\", "/"))).strip().lstrip("/")
        parts = PurePosixPath(rel).parts
        if len(parts) >= 2 and parts[0] == SKILLS_EXTERNAL_MOUNT:
            provider_id = str(parts[1]).strip()
            root = self._provider_root_path(provider_id)
            if root is None:
                raise ValueError(f"unknown external skill provider: {provider_id}")
            tail = PurePosixPath(*parts[2:]).as_posix() if len(parts) > 2 else "."
            return safe_path(tail or ".", root)
        return safe_path(rel or ".", self.skills_root)

    def public_virtual_skill_path_for_abs(self, path: Path) -> str:
        try:
            resolved = path.resolve()
        except Exception:
            return ""
        try:
            rel = resolved.relative_to(self.skills_root.resolve()).as_posix()
            public = SKILLS_VIRTUAL_PREFIX if rel in {"", "."} else f"{SKILLS_VIRTUAL_PREFIX}/{rel}"
            return public.replace("//", "/")
        except Exception:
            pass
        for provider_id in sorted(self.providers.keys()):
            root = self._provider_root_path(provider_id)
            if root is None:
                continue
            try:
                if root == self.skills_root.resolve() or root.is_relative_to(self.skills_root.resolve()):
                    continue
            except Exception:
                pass
            try:
                rel = resolved.relative_to(root).as_posix()
            except Exception:
                continue
            prefix = self._provider_virtual_prefix(provider_id)
            public = prefix if rel in {"", "."} else f"{prefix}/{rel}"
            return public.replace("//", "/")
        return ""

    def shell_virtual_mappings(self) -> list[tuple[str, str]]:
        rows: list[tuple[str, str]] = []
        try:
            skills_root = self.skills_root.resolve()
        except Exception:
            skills_root = self.skills_root
        for provider_id in sorted(self.providers.keys()):
            root = self._provider_root_path(provider_id)
            if root is None:
                continue
            try:
                if root == skills_root or root.is_relative_to(skills_root):
                    continue
            except Exception:
                pass
            rows.append((self._provider_virtual_prefix(provider_id), str(root)))
        rows.sort(key=lambda x: len(x[0]), reverse=True)
        return rows

    def _public_skill_locator(self, raw_locator: str) -> str:
        raw = str(raw_locator or "").strip()
        if not raw:
            return ""
        if raw == "(builtin)":
            return raw
        if _is_http_url(raw):
            return raw
        base, sep, frag = raw.partition("#")
        if _is_http_url(base):
            return raw
        try:
            candidate = Path(base)
        except Exception:
            return raw
        resolved: Path | None = None
        try:
            resolved = candidate.resolve() if candidate.is_absolute() else (self.skills_root / candidate).resolve()
        except Exception:
            resolved = None
        if resolved is not None:
            try:
                rel = resolved.relative_to(self.skills_root.resolve()).as_posix()
                public = SKILLS_VIRTUAL_PREFIX if rel in {"", "."} else f"{SKILLS_VIRTUAL_PREFIX}/{rel}"
                public = public.replace("//", "/")
                return public + (f"#{frag}" if sep else "")
            except Exception:
                pass
        if candidate.is_absolute():
            return "(external-local-path)"
        rel = candidate.as_posix().strip().lstrip("/")
        if rel in {"", "."}:
            public = SKILLS_VIRTUAL_PREFIX
            return public + (f"#{frag}" if sep else "")
        if ".." not in PurePosixPath(rel).parts:
            public = f"{SKILLS_VIRTUAL_PREFIX}/{rel}".replace("//", "/")
            return public + (f"#{frag}" if sep else "")
        return raw

    def _absolute_skill_locator(self, raw_locator: str) -> str:
        raw = str(raw_locator or "").strip()
        if not raw or raw == "(builtin)":
            return ""
        if _is_http_url(raw):
            return ""
        base = raw.partition("#")[0].strip()
        if not base or _is_http_url(base):
            return ""
        try:
            candidate = Path(base)
        except Exception:
            return ""
        try:
            resolved = candidate.resolve() if candidate.is_absolute() else (self.skills_root / candidate).resolve()
        except Exception:
            return ""
        return str(resolved)

    def _public_attachment_locator(self, item: dict) -> tuple[str, str]:
        source = str(item.get("virtual_path", "") or "").strip()
        if not source:
            source = self._public_provider_locator(
                str(item.get("abs_path", "") or ""),
                str(item.get("provider_id", "") or ""),
            )
        virtual_path = source if source.startswith(f"{SKILLS_VIRTUAL_PREFIX}/") else ""
        return source, virtual_path

    def _public_provider_locator(self, raw_locator: str, provider_id: str = "") -> str:
        public = self._public_provider_path(provider_id, raw_locator)
        if public == "(external-local-path)":
            return ""
        return public

    def _register_provider(
        self,
        provider_id: str,
        protocol: str,
        version: str,
        description: str,
        root: Path | None = None,
        config_path: Path | None = None,
    ):
        provider_id = self._sanitize_provider_id(provider_id, "provider")
        if provider_id in self.providers:
            i = 2
            base = provider_id
            while f"{base}-{i}" in self.providers:
                i += 1
            provider_id = f"{base}-{i}"
        self.providers[provider_id] = {
            "provider_id": provider_id,
            "protocol": protocol,
            "protocol_version": version,
            "description": description,
            "root": str(root.resolve()) if root else "",
            "config_path": str(config_path.resolve()) if config_path else "",
            "skill_count": 0,
        }
        return provider_id

    def _collect_attachments(
        self,
        skill_dir: Path,
        *,
        provider_id: str = "",
        skip_name: str = "SKILL.md",
        globs: list[str] | None = None,
        base_dir: Path | None = None,
        entrypoints: list[str] | None = None,
    ) -> list[dict]:
        attachments: list[dict] = []
        seen: set[str] = set()
        base = base_dir or skill_dir
        entrypoint_set = {str(x).strip() for x in (entrypoints or []) if str(x).strip()}
        candidates: list[Path] = []
        effective_globs = globs or list(SKILL_DEFAULT_ATTACHMENT_GLOBS)
        if effective_globs:
            for pattern in effective_globs:
                for fp in sorted(base.glob(pattern)):
                    candidates.append(fp)
        for rel in sorted(entrypoint_set):
            target = (skill_dir / rel).resolve()
            if target.exists():
                candidates.append(target)
        try:
            allowed_root = base.resolve()
        except Exception:
            allowed_root = base
        for fp in candidates:
            try:
                resolved_fp = fp.resolve()
                resolved_fp.relative_to(allowed_root)
            except Exception:
                self.warnings.append(f"blocked skill resource outside provider root: {fp}")
                continue
            if fp.is_symlink() or not resolved_fp.is_file():
                if fp.is_symlink():
                    self.warnings.append(f"blocked symlink skill resource: {fp}")
                continue
            if fp.name in {skip_name, ".DS_Store"}:
                continue
            rel = resolved_fp.relative_to(allowed_root).as_posix()
            if rel in seen:
                continue
            seen.add(rel)
            text = try_read_text(fp)
            if text is None and rel not in entrypoint_set:
                continue
            try:
                skill_rel = resolved_fp.relative_to(self.skills_root.resolve()).as_posix()
            except Exception:
                skill_rel = rel
            size = 0
            try:
                size = int(fp.stat().st_size or 0)
            except Exception:
                size = len(text or "")
            attachments.append(
                {
                    "path": rel,
                    "abs_path": str(resolved_fp),
                    "virtual_path": self._public_provider_path(provider_id, resolved_fp)
                    or f"{SKILLS_VIRTUAL_PREFIX}/{skill_rel}".replace("//", "/"),
                    "provider_id": provider_id,
                    "content": text or "",
                    "text_available": text is not None,
                    "size": size,
                    "priority": 2 if rel in entrypoint_set else 1,
                }
            )
        return attachments

    def _register_skill(
        self,
        *,
        provider_id: str,
        protocol: str,
        protocol_version: str,
        name: str,
        description: str,
        meta: dict,
        body: str,
        skill_path: str,
        attachments: list[dict],
    ):
        raw_name = (name or "").strip()
        skill_name = raw_name or Path(skill_path).parent.name or "skill"
        key = f"{provider_id}:{skill_name}"
        if key in self.skills:
            i = 2
            while f"{key}#{i}" in self.skills:
                i += 1
            key = f"{key}#{i}"
        record = {
            "id": key,
            "name": skill_name,
            "description": (description or "-").strip() or "-",
            "provider_id": provider_id,
            "protocol": protocol,
            "protocol_version": protocol_version,
            "meta": dict(meta or {}),
            "body": (body or "").strip(),
            "skill_path": self._public_provider_path(provider_id, skill_path),
            "skill_abs_path": self._absolute_skill_locator(skill_path),
            "attachments": attachments,
        }
        self.skills[key] = record
        p = self.providers.get(provider_id)
        if p:
            p["skill_count"] = int(p.get("skill_count", 0)) + 1
        self._register_alias(skill_name, key)
        for alias in self._skill_aliases(meta):
            if alias != skill_name:
                self._register_alias(alias, key)

    def _load_skill_file(self, skill_file: Path, provider_id: str, protocol: str, protocol_version: str):
        raw = try_read_text(skill_file)
        if raw is None:
            return
        meta, body = parse_front_matter(raw)
        skill_dir = skill_file.parent
        # Keep routing-table references searchable without making metadata
        # recall reopen or parse the potentially large SKILL.md body. Skills
        # that ship reference guides can expose stable technique entrypoints;
        # existing domain term groups provide multilingual aliases generically.
        reference_files = sorted(skill_dir.glob("reference/*.md"))
        if reference_files:
            meta = dict(meta)
            existing_cc = meta.get("clouds_coder")
            clouds_coder = dict(existing_cc) if isinstance(existing_cc, dict) else {}
            entrypoints = _meta_string_list(clouds_coder.get("entrypoints"))
            reference_stems = {
                re.sub(r"[-_]+", " ", reference_file.stem).casefold()
                for reference_file in reference_files
            }
            for reference_file in reference_files:
                stem = reference_file.stem
                entrypoint = f"techniques/{stem}.md"
                if entrypoint not in entrypoints:
                    entrypoints.append(entrypoint)
            triggers = _meta_string_list(clouds_coder.get("triggers"))
            for group in globals().get("RAG_TERM_GROUPS", ()):
                terms = [str(term).strip() for term in group if str(term).strip()]
                if not terms:
                    continue
                normalized_terms = [
                    re.sub(r"[-_]+", " ", term).casefold() for term in terms
                ]
                if not any(
                    part and (part in stem or stem in part)
                    for stem in reference_stems
                    for term in normalized_terms
                    for part in term.split()
                    if len(part) >= 3
                ):
                    continue
                for term in terms:
                    if term not in triggers:
                        triggers.append(term)
                    for token in re.findall(r"[A-Za-z][A-Za-z0-9+#.-]{2,}", term):
                        if token not in triggers:
                            triggers.append(token)
            if triggers:
                clouds_coder["triggers"] = triggers
            clouds_coder["entrypoints"] = entrypoints
            meta["clouds_coder"] = clouds_coder
        # Standard SKILL.md frontmatter stays portable (name + description).
        # Clouds Coder provider/protocol extensions live in a sidecar and are
        # merged only at runtime.
        cc_sidecar = skill_dir / "agents" / "clouds-coder.yaml"
        if cc_sidecar.exists() and cc_sidecar.is_file() and not cc_sidecar.is_symlink():
            try:
                sidecar_raw = cc_sidecar.read_text(encoding="utf-8")
                sidecar = _yaml.safe_load(sidecar_raw) if _yaml is not None else {}
                if isinstance(sidecar, dict):
                    section = sidecar.get("clouds_coder", sidecar)
                    if isinstance(section, dict):
                        meta = dict(meta)
                        meta["clouds_coder"] = dict(section)
            except Exception as exc:
                self.warnings.append(f"{cc_sidecar}: invalid Clouds Coder sidecar: {exc}")
        name = str(meta.get("name", "")).strip() or skill_dir.name
        desc = str(meta.get("description", "-"))
        attachments = self._collect_attachments(
            skill_dir,
            provider_id=provider_id,
            skip_name=skill_file.name,
            globs=self._skill_attachment_globs(meta),
            entrypoints=self._skill_entrypoints(meta),
        )
        self._register_skill(
            provider_id=provider_id,
            protocol=protocol,
            protocol_version=protocol_version,
            name=name,
            description=desc,
            meta=meta,
            body=body,
            skill_path=str(skill_file.resolve()),
            attachments=attachments,
        )

    def _load_local_skills(self):
        provider_id = self._register_provider(
            provider_id="local",
            protocol=SKILL_PROTOCOL_LOCAL,
            version="1.0",
            description="Auto-discovered local SKILL.md files",
            root=self.skills_root,
        )
        excluded = []
        for segment in ("providers", "clawhub"):
            p = self.skills_root / segment
            if p.exists():
                excluded.append(p.resolve())
        for skill_file in sorted(self.skills_root.rglob("SKILL.md")):
            resolved = skill_file.resolve()
            if any(resolved.is_relative_to(root) for root in excluded):
                continue
            self._load_skill_file(skill_file, provider_id, SKILL_PROTOCOL_LOCAL, "1.0")
        # Extended discovery: plugins/*/skills/*/SKILL.md (Minimax format)
        plugins_dir = self.skills_root / "plugins"
        if plugins_dir.exists() and plugins_dir.is_dir():
            for skill_file in sorted(plugins_dir.rglob("SKILL.md")):
                resolved = skill_file.resolve()
                if any(resolved.is_relative_to(root) for root in excluded):
                    continue
                # Skip if already loaded (may overlap with rglob above)
                candidate_key = f"local:{skill_file.parent.name}"
                if candidate_key in self.skills:
                    continue
                self._load_skill_file(skill_file, provider_id, SKILL_PROTOCOL_LOCAL, "1.0")
        # Load .claude-plugin manifests for skill discovery
        self._load_claude_plugin_manifests()

    def _load_claude_plugin_manifests(self):
        """Load skills referenced in .claude-plugin/plugin.json or marketplace.json.

        Supports Minimax plugin.json and Anthropic marketplace.json formats.
        This enables discovery of skills in nested plugin directories.
        """
        for manifest_name in ("plugin.json", "marketplace.json"):
            manifest_path = self.skills_root / ".claude-plugin" / manifest_name
            if not manifest_path.exists():
                continue
            try:
                raw = json.loads(manifest_path.read_text(encoding="utf-8"))
                if not isinstance(raw, dict):
                    continue
            except Exception:
                continue
            # Anthropic marketplace.json: plugins[].skills[] → paths
            plugins = raw.get("plugins", [])
            if isinstance(plugins, list):
                for plugin in plugins:
                    if not isinstance(plugin, dict):
                        continue
                    skill_paths = plugin.get("skills", [])
                    if not isinstance(skill_paths, list):
                        continue
                    for skill_rel in skill_paths:
                        skill_dir = (self.skills_root / str(skill_rel).strip()).resolve()
                        skill_file = skill_dir / "SKILL.md"
                        if skill_file.exists():
                            # Check if already loaded
                            try:
                                name = skill_dir.name
                                if any(name == s.get("name") for s in self.skills.values()):
                                    continue
                            except Exception:
                                pass
                            self._load_skill_file(
                                skill_file, "local", SKILL_PROTOCOL_LOCAL, "1.0",
                            )

    def _load_http_provider(self, manifest_path: Path, cfg: dict):
        endpoint = str(cfg.get("endpoint", "")).strip()
        if not endpoint:
            self.warnings.append(f"{manifest_path.name}: missing endpoint for {SKILL_PROTOCOL_HTTP_JSON}")
            return
        provider_id = self._register_provider(
            provider_id=str(cfg.get("provider_id") or manifest_path.stem),
            protocol=SKILL_PROTOCOL_HTTP_JSON,
            version=str(cfg.get("version", "1.0")).strip() or "1.0",
            description=str(cfg.get("description", "HTTP JSON provider")).strip() or "HTTP JSON provider",
            config_path=manifest_path,
        )
        timeout = int(cfg.get("timeout", 4))
        req = Request(endpoint, method="GET")
        try:
            with urlopen(req, timeout=timeout) as resp:
                payload = json.loads(resp.read().decode("utf-8"))
        except Exception as exc:
            self.warnings.append(f"{manifest_path.name}: HTTP provider fetch failed: {exc}")
            return
        for item in payload.get("skills", []):
            if not isinstance(item, dict):
                continue
            name = str(item.get("name", "")).strip()
            if not name:
                continue
            body = str(item.get("content", "")).strip()
            if not body:
                continue
            meta = item.get("meta", {}) if isinstance(item.get("meta"), dict) else {}
            desc = str(item.get("description", meta.get("description", "-")))
            attachments = []
            for a in item.get("attachments", []):
                if not isinstance(a, dict):
                    continue
                apath = str(a.get("path", "")).strip() or f"{name}.txt"
                acontent = str(a.get("content", ""))
                attachments.append({"path": apath, "abs_path": endpoint, "content": acontent})
            self._register_skill(
                provider_id=provider_id,
                protocol=SKILL_PROTOCOL_HTTP_JSON,
                protocol_version=str(cfg.get("version", "1.0")).strip() or "1.0",
                name=name,
                description=desc,
                meta=meta,
                body=body,
                skill_path=f"{endpoint}#{name}",
                attachments=attachments,
            )

    def _load_clawhub_provider(self, manifest_path: Path, cfg: dict):
        root_value = str(cfg.get("root", ".")).strip() or "."
        root = (manifest_path.parent / root_value).resolve() if not Path(root_value).is_absolute() else Path(root_value).resolve()
        provider_id = self._register_provider(
            provider_id=str(cfg.get("provider_id") or f"clawhub-{manifest_path.stem}"),
            protocol=SKILL_PROTOCOL_CLAWHUB,
            version=str(cfg.get("version", "1.0")).strip() or "1.0",
            description=str(cfg.get("description", "ClawHub skill provider")).strip() or "ClawHub skill provider",
            root=root,
            config_path=manifest_path,
        )
        explicit = cfg.get("skills")
        if isinstance(explicit, list) and explicit:
            for row in explicit:
                if not isinstance(row, dict):
                    continue
                file_hint = str(row.get("file") or row.get("path") or "").strip()
                inline_content = row.get("content")
                source_path = None
                raw = ""
                if file_hint:
                    source_path = (root / file_hint).resolve() if not Path(file_hint).is_absolute() else Path(file_hint).resolve()
                    raw = try_read_text(source_path) or ""
                elif inline_content is not None:
                    raw = str(inline_content)
                if not raw:
                    continue
                meta, body = parse_front_matter(raw)
                name = str(row.get("name") or meta.get("name") or (source_path.parent.name if source_path else "clawhub_skill"))
                desc = str(row.get("description") or meta.get("description", "-"))
                attachment_globs = row.get("attachments")
                globs = [str(x) for x in attachment_globs if isinstance(x, str)] if isinstance(attachment_globs, list) else None
                skill_dir = source_path.parent if source_path else root
                attachments = self._collect_attachments(
                    skill_dir,
                    skip_name=source_path.name if source_path else "SKILL.md",
                    globs=globs,
                    base_dir=root if globs else None,
                    entrypoints=self._skill_entrypoints(meta),
                )
                self._register_skill(
                    provider_id=provider_id,
                    protocol=SKILL_PROTOCOL_CLAWHUB,
                    protocol_version=str(cfg.get("version", "1.0")).strip() or "1.0",
                    name=name,
                    description=desc,
                    meta=meta,
                    body=body,
                    skill_path=str(source_path.resolve()) if source_path else str(manifest_path.resolve()),
                    attachments=attachments,
                )
            return
        if not root.exists():
            self.warnings.append(f"{manifest_path.name}: clawhub root not found: {root}")
            return
        for skill_file in sorted(root.rglob("SKILL.md")):
            self._load_skill_file(skill_file, provider_id, SKILL_PROTOCOL_CLAWHUB, "1.0")

    def _load_manifest_providers(self):
        providers_dir = self.skills_root / "providers"
        if not providers_dir.exists():
            return
        for manifest_path in sorted(providers_dir.rglob("*.json")):
            raw = try_read_text(manifest_path)
            if not raw:
                continue
            try:
                cfg = json.loads(raw)
            except Exception:
                self.warnings.append(f"{manifest_path.name}: invalid JSON")
                continue
            if not isinstance(cfg, dict):
                continue
            protocol = str(cfg.get("protocol", "")).strip()
            if not protocol:
                continue
            if protocol == SKILL_PROTOCOL_CLAWHUB:
                self._load_clawhub_provider(manifest_path, cfg)
                continue
            if protocol == SKILL_PROTOCOL_HTTP_JSON:
                self._load_http_provider(manifest_path, cfg)
                continue
            if protocol == SKILL_PROTOCOL_LOCAL:
                root_hint = str(cfg.get("root", ".")).strip() or "."
                root = (manifest_path.parent / root_hint).resolve() if not Path(root_hint).is_absolute() else Path(root_hint).resolve()
                provider_id = self._register_provider(
                    provider_id=str(cfg.get("provider_id") or f"local-{manifest_path.stem}"),
                    protocol=SKILL_PROTOCOL_LOCAL,
                    version=str(cfg.get("version", "1.0")).strip() or "1.0",
                    description=str(cfg.get("description", "Local manifest provider")).strip() or "Local manifest provider",
                    root=root,
                    config_path=manifest_path,
                )
                if root.exists():
                    for skill_file in sorted(root.rglob("SKILL.md")):
                        self._load_skill_file(skill_file, provider_id, SKILL_PROTOCOL_LOCAL, "1.0")
                else:
                    self.warnings.append(f"{manifest_path.name}: local root not found: {root}")
                continue
            self.warnings.append(f"{manifest_path.name}: unsupported protocol '{protocol}'")

    def _load_clawhub_autodetect(self):
        clawhub_root = self.skills_root / "clawhub"
        if not clawhub_root.exists():
            return
        has_clawhub_provider = any(p.get("protocol") == SKILL_PROTOCOL_CLAWHUB for p in self.providers.values())
        if has_clawhub_provider:
            return
        provider_id = self._register_provider(
            provider_id="clawhub-default",
            protocol=SKILL_PROTOCOL_CLAWHUB,
            version="1.0",
            description="Auto-discovered clawhub bridge provider",
            root=clawhub_root,
        )
        for skill_file in sorted(clawhub_root.rglob("SKILL.md")):
            self._load_skill_file(skill_file, provider_id, SKILL_PROTOCOL_CLAWHUB, "1.0")

    def _skills_fingerprint(self) -> str:
        if not self.skills_root.exists():
            return ""
        sha = hashlib.sha256()
        files: list[Path] = []
        files.extend(sorted(self.skills_root.rglob("*")))
        providers_dir = self.skills_root / "providers"
        if providers_dir.exists():
            files.extend(sorted(providers_dir.rglob("*.json")))
        manifest = self.skills_root / "clawhub" / "builtin" / "_builtin_manifest.json"
        if manifest.exists():
            files.append(manifest)
        seen: set[str] = set()
        for fp in files:
            try:
                resolved = str(fp.resolve())
            except Exception:
                continue
            if resolved in seen:
                continue
            seen.add(resolved)
            if not fp.exists() or not fp.is_file():
                continue
            try:
                rel = fp.resolve().relative_to(self.skills_root.resolve()).as_posix()
            except Exception:
                rel = fp.name
            try:
                st = fp.stat()
                size = int(st.st_size or 0)
                mtime_ns = int(getattr(st, "st_mtime_ns", int(st.st_mtime * 1_000_000_000)))
            except Exception:
                size = 0
                mtime_ns = 0
            sha.update(rel.encode("utf-8", errors="ignore"))
            sha.update(b"|")
            sha.update(str(size).encode("ascii", errors="ignore"))
            sha.update(b"|")
            sha.update(str(mtime_ns).encode("ascii", errors="ignore"))
            sha.update(b"\n")
        return sha.hexdigest()

    def reload(self, force: bool = False):
        now = now_ts()
        if (not force) and self.last_reload_ts > 0 and (now - self.last_reload_ts) < SKILL_REFRESH_MIN_INTERVAL_SECONDS:
            return
        fp = self._skills_fingerprint()
        if (not force) and fp and self.fingerprint and fp == self.fingerprint and self.skills:
            self.last_reload_ts = now
            return
        self.skills = {}
        self.aliases = {}
        self.ambiguous = {}
        self.providers = {}
        self.warnings = []
        if not self.skills_root.exists():
            self.fingerprint = fp
            self.last_reload_ts = now
            return
        self._load_local_skills()
        self._load_manifest_providers()
        self._load_clawhub_autodetect()
        self._load_external_skill_roots()
        self._inject_builtin_skills()
        self.fingerprint = fp
        self.last_reload_ts = now

    def _load_external_skill_roots(self):
        """Discover and load skills from external directories adjacent to skills_root.

        Scans the parent directory of skills_root for known skill library patterns:
        - Directories containing SKILL.md at root (e.g., academic-pptx-skill-main/)
        - Directories containing skills/*/SKILL.md (e.g., skills-main/skills/, Minimax/skills/)
        - Directories containing source-code/skills/*/SKILL.md (e.g., kimi-agent-internals-main/)
        - Directories containing plugins/*/skills/*/SKILL.md (e.g., Minimax/plugins/)

        Each external directory is registered as a separate provider for clean namespacing.
        """
        workspace = self.skills_root.parent
        if not workspace.exists():
            return
        skills_root_resolved = self.skills_root.resolve()
        already_loaded_names = {s.get("name", "") for s in self.skills.values() if s.get("name")}
        # Scan workspace for directories that look like skill libraries
        try:
            candidates = sorted(
                (d for d in workspace.iterdir() if d.is_dir() and d.resolve() != skills_root_resolved),
                key=lambda p: p.name.lower(),
            )
        except Exception:
            return
        for candidate in candidates:
            skill_files: list[Path] = []
            # Pattern 1: Root-level SKILL.md (e.g., academic-pptx-skill-main/SKILL.md)
            root_skill = candidate / "SKILL.md"
            if root_skill.exists():
                skill_files.append(root_skill)
            # Pattern 2: skills/*/SKILL.md (e.g., skills-main/skills/docx/SKILL.md)
            skills_subdir = candidate / "skills"
            if skills_subdir.exists() and skills_subdir.is_dir():
                try:
                    for sf in sorted(skills_subdir.rglob("SKILL.md")):
                        skill_files.append(sf)
                except Exception:
                    pass
            # Pattern 3: source-code/skills/*/SKILL.md (e.g., kimi-agent-internals-main/)
            source_skills = candidate / "source-code" / "skills"
            if source_skills.exists() and source_skills.is_dir():
                try:
                    for sf in sorted(source_skills.rglob("SKILL.md")):
                        skill_files.append(sf)
                except Exception:
                    pass
            # Pattern 4: plugins/*/skills/*/SKILL.md (e.g., Minimax/plugins/pptx-plugin/)
            plugins_dir = candidate / "plugins"
            if plugins_dir.exists() and plugins_dir.is_dir():
                try:
                    for sf in sorted(plugins_dir.rglob("SKILL.md")):
                        skill_files.append(sf)
                except Exception:
                    pass
            if not skill_files:
                continue
            # Register this external directory as a provider
            provider_name = re.sub(r"[^A-Za-z0-9]+", "-", candidate.name.lower()).strip("-") or "external"
            provider_id = self._register_provider(
                provider_id=f"ext-{provider_name}",
                protocol=SKILL_PROTOCOL_LOCAL,
                version="1.0",
                description=f"External skill library: {candidate.name}",
                root=candidate,
            )
            loaded = 0
            for skill_file in skill_files:
                try:
                    raw = try_read_text(skill_file)
                    if raw is None:
                        continue
                    meta, _ = parse_front_matter(raw)
                    name = str(meta.get("name", "")).strip() or skill_file.parent.name
                    # Skip duplicates (same name already loaded from local skills)
                    if name in already_loaded_names:
                        continue
                    self._load_skill_file(skill_file, provider_id, SKILL_PROTOCOL_LOCAL, "1.0")
                    already_loaded_names.add(name)
                    loaded += 1
                except Exception:
                    continue
            if loaded > 0:
                self.providers[provider_id]["skill_count"] = loaded

    def _inject_builtin_skills(self):
        """Register built-in skill guides for small-model support."""
        provider_id = "builtin"
        if not self._provider_exists(provider_id):
            self._register_provider(
                provider_id, "builtin", "1.0",
                "Built-in skill guides for agent operation",
            )
        for skill_name, data in _BUILTIN_SKILLS.items():
            key = f"{provider_id}:{skill_name}"
            if key in self.skills:
                continue
            self._register_skill(
                provider_id=provider_id,
                protocol="builtin",
                protocol_version="1.0",
                name=skill_name,
                description=data["description"],
                meta={"builtin": True},
                body=data["body"],
                skill_path="(builtin)",
                attachments=[],
            )

    def descriptions(self, max_items: int = SKILL_PROMPT_MAX_ITEMS, max_chars: int = SKILL_PROMPT_MAX_CHARS) -> str:
        if not self.skills:
            return "(no skills)"
        lines = [f"(indexed skills: {len(self.skills)})"]
        shown = 0
        for key, data in sorted(self.skills.items()):
            if shown >= max(1, int(max_items or SKILL_PROMPT_MAX_ITEMS)):
                break
            simple = data.get("name", key)
            label = simple if self.aliases.get(simple) == key else key
            desc = data.get("description", "-")
            aliases = [
                x for x in self._skill_aliases(data.get("meta", {}))
                if x and x != simple
            ][:2]
            if aliases:
                desc = f"{desc} (aliases: {', '.join(aliases)})"
            lines.append(f"- {label}: {desc} [{data.get('provider_id')} | {data.get('protocol')}]")
            shown += 1
        remaining = max(0, len(self.skills) - shown)
        if remaining > 0:
            lines.append(f"... ({remaining} more skills omitted; use list_skills/load_skill on demand)")
        if self.ambiguous:
            lines.append("Ambiguous names require provider:name format.")
        if self.warnings:
            lines.append(f"Skill warnings: {len(self.warnings)}")
        return trim("\n".join(lines), max(400, int(max_chars or SKILL_PROMPT_MAX_CHARS)))

    def list_names(self) -> list[str]:
        names = set(self.skills.keys())
        names.update(self.aliases.keys())
        return sorted(names)

    def list_metadata(self) -> list[dict]:
        out = [self._skill_metadata_record(key, data) for key, data in sorted(self.skills.items())]
        if self.ambiguous:
            out.append(
                {
                    "id": "_warnings",
                    "name": "_warnings",
                    "qualified_name": "_warnings",
                    "description": "Ambiguous skill aliases detected",
                    "provider_id": "system",
                    "protocol": "system",
                    "protocol_version": "1.0",
                    "meta": {"ambiguous": self.ambiguous, "warnings": self.warnings},
                    "skill_path": "",
                    "virtual_path": "",
                    "attachments": [],
                    "aliases": [],
                }
            )
        return out

    def canonicalize_id(self, name: object) -> dict:
        """Resolve any public skill identifier to one canonical id.

        The structured response is intentionally separate from ``_resolve_name``
        so older callers that expect a ``(key, error)`` tuple remain compatible.
        """
        requested = str(name or "").strip()
        if not requested:
            return {"ok": False, "requested": requested, "error": "skill name required", "code": "missing"}
        exact = self.skills.get(requested)
        if exact is not None:
            return {"ok": True, "requested": requested, "canonical_id": requested, "name": exact.get("name", requested)}
        candidates: list[str] = []
        folded = requested.casefold()
        for key, data in self.skills.items():
            names = [key, str(data.get("name", "") or "")]
            meta = data.get("meta", {}) if isinstance(data.get("meta"), dict) else {}
            names.extend(self._skill_aliases(meta))
            if any(str(value or "").strip().casefold() == folded for value in names):
                candidates.append(key)
        if requested in self.ambiguous:
            candidates = list(self.ambiguous.get(requested, []))
        if len(candidates) == 1:
            key = candidates[0]
            return {"ok": True, "requested": requested, "canonical_id": key, "name": self.skills[key].get("name", key)}
        if len(candidates) > 1:
            return {
                "ok": False,
                "requested": requested,
                "error": f"ambiguous skill '{requested}'",
                "code": "ambiguous",
                "candidates": sorted(candidates),
            }
        return {
            "ok": False,
            "requested": requested,
            "error": f"unknown skill '{requested}'",
            "code": "unknown",
            "candidates": [],
        }

    # Friendly aliases used by IDE/runtime integrations.
    canonicalize = canonicalize_id
    resolve_canonical = canonicalize_id

    def recall_metadata(
        self,
        focus: str = "",
        *,
        step: str = "",
        phase: str = "",
        limit: int = 12,
        include_infrastructure: bool = False,
    ) -> list[dict]:
        """Recall a bounded metadata candidate set without loading skill bodies."""
        raw_query = f"{focus or ''}\n{step or ''}\n{phase or ''}"
        # Runtime wrappers describe where the request came from, not what the
        # user is trying to accomplish.  Letting these lines participate in
        # recall made tokens such as ``IDE`` and ``workspace`` outrank the
        # actual current Todo/Plan step.
        meaningful_lines: list[str] = []
        for raw_line in normalize_embedded_newlines(raw_query).splitlines():
            line = re.sub(r"\s+", " ", str(raw_line or "").strip())
            if not line:
                continue
            if re.fullmatch(
                r"(?:ide programming request\.?|ide workspace\s*(?:\([^)]*\))?)\s*",
                line,
                flags=re.IGNORECASE,
            ) or re.match(r"^(?:workspace root|writable path)\s*:", line, flags=re.IGNORECASE):
                continue
            meaningful_lines.append(line)
        query = re.sub(r"\s+", " ", " ".join(meaningful_lines)).strip().casefold()
        generic_tokens = {
            "the", "and", "for", "with", "from", "this", "that", "use", "build", "create", "analyze",
            "task", "step", "current", "plan", "phase", "direct", "objective", "execution", "run", "start",
            "auto", "ide", "programming", "request", "workspace", "root", "writable", "path", "session",
        }
        tokens: list[str] = []
        seen_tokens: set[str] = set()
        for token in re.findall(r"[\w.+#-]{2,}", query, flags=re.UNICODE):
            normalized = token.strip("._+-").casefold()
            if not normalized or normalized in generic_tokens or normalized in seen_tokens:
                continue
            seen_tokens.add(normalized)
            tokens.append(normalized)

        def _ascii_term_match(haystack: str, term: str) -> bool:
            if not term:
                return False
            if re.search(r"[\u3400-\u9fff]", term):
                return term in haystack
            return bool(re.search(r"(?<![A-Za-z0-9_])" + re.escape(term) + r"(?![A-Za-z0-9_])", haystack))

        scored: list[tuple[float, str, dict]] = []
        for key, data in self.skills.items():
            meta = self._skill_metadata_record(key, data)
            if meta.get("infrastructure_only") and not include_infrastructure:
                continue
            negatives = [str(x).casefold() for x in meta.get("negative_triggers", [])]
            negative_hit = next((x for x in negatives if x and x in query), "")
            if negative_hit:
                meta["filter_reason"] = f"negative_trigger:{negative_hit}"
                continue
            score = 0.0
            # Explicit trigger/keyword/name matches are strong. Description is
            # deliberately weak so words like Build/Use/Analyze do not dominate.
            seen_terms: set[str] = set()
            for value in list(meta.get("triggers", [])) + list(meta.get("keywords", [])) + list(meta.get("aliases", [])):
                raw_term = str(value or "").strip()
                term = raw_term.casefold()
                if not term or term in seen_terms or term in generic_tokens | {"skill"}:
                    continue
                seen_terms.add(term)
                if _ascii_term_match(query, term):
                    is_cjk = bool(re.search(r"[\u3400-\u9fff]", term))
                    is_acronym = len(raw_term) >= 2 and raw_term.isupper()
                    score += 6.0 if is_cjk or is_acronym or " " in term or len(term) >= 6 else 2.0
            name = str(meta.get("name", "") or "").casefold()
            if name and _ascii_term_match(query, name):
                score += 8.0
            name_tokens = {
                part.casefold()
                for part in re.findall(r"[A-Za-z0-9+#.]{2,}|[\u3400-\u9fff]{2,}", name, flags=re.UNICODE)
            }
            description = str(meta.get("description", "") or "").casefold()
            description_tokens = {
                part.casefold()
                for part in re.findall(r"[A-Za-z0-9+#.]{3,}|[\u3400-\u9fff]{2,}", description, flags=re.UNICODE)
            }
            for token in tokens:
                # Name matching uses normalized segments.  Arbitrary substring
                # matching made ``ide`` match the middle of ``video``.
                if token in name_tokens:
                    score += 2.5
                elif token in description_tokens:
                    score += 0.35
            # Keep unscored rows available only when the caller asks for an
            # explicit catalog; automatic focus selection should stay empty.
            if score > 0:
                scored.append((score, str(meta.get("canonical_id", key)), meta))
        scored.sort(key=lambda row: (-row[0], row[1].casefold()))
        return [
            dict(row[2], score=round(row[0], 4))
            for row in scored[: max(1, min(50, int(limit or 12)))]
        ]

    metadata_recall = recall_metadata

    @staticmethod
    def _selection_json(raw: object) -> object:
        if isinstance(raw, (dict, list)):
            return raw
        text = str(raw or "").strip()
        if not text:
            return None
        fence = re.search(r"```(?:json)?\s*([\s\S]*?)```", text, re.IGNORECASE)
        if fence:
            text = fence.group(1).strip()
        try:
            return json.loads(text)
        except Exception:
            match = re.search(r"\{[\s\S]*\}|\[[\s\S]*\]", text)
            if not match:
                return None
            try:
                return json.loads(match.group(0))
            except Exception:
                return None

    def select_skills(
        self,
        focus: str = "",
        *,
        step: str = "",
        phase: str = "",
        llm_selector=None,
        limit: int = 3,
        candidate_limit: int = 12,
        include_infrastructure: bool = False,
        active_ids: list[str] | None = None,
    ) -> dict:
        """Shared recall -> semantic selection -> strict validation pipeline."""
        started = time.monotonic()
        candidates = self.recall_metadata(
            focus,
            step=step,
            phase=phase,
            limit=candidate_limit,
            include_infrastructure=include_infrastructure,
        )
        result = {
            "focus": trim(str(focus or ""), 500),
            "step": trim(str(step or ""), 300),
            "phase": trim(str(phase or ""), 80),
            "candidates": candidates,
            "selected": [],
            "selection_order": [],
            "filtered": [],
            "conflicts": [],
            "requires": [],
            "fallback": "none",
            "fallback_type": "none",
            "duration_ms": 0,
        }
        query_text = re.sub(r"\s+", " ", f"{focus or ''} {step or ''} {phase or ''}").casefold()
        for key, data in self.skills.items():
            meta_row = self._skill_metadata_record(key, data)
            negative_hit = next(
                (str(value) for value in meta_row.get("negative_triggers", []) or [] if str(value).casefold() in query_text),
                "",
            )
            if negative_hit:
                result["filtered"].append({"id": key, "reason": f"negative_trigger:{negative_hit}"})
                continue
            if meta_row.get("infrastructure_only") and not include_infrastructure:
                name = str(meta_row.get("name", "") or "").casefold()
                if name and name in query_text:
                    result["filtered"].append({"id": key, "reason": "infrastructure_only"})
        if not candidates:
            result["fallback"] = result["fallback_type"] = "empty"
            result["duration_ms"] = int((time.monotonic() - started) * 1000)
            return result
        candidate_ids = {str(row.get("canonical_id", row.get("id", ""))) for row in candidates}
        raw = None
        if callable(llm_selector):
            try:
                raw = llm_selector(candidates)
            except Exception as exc:
                result["fallback"] = result["fallback_type"] = "llm_error"
                result["filtered"].append({"id": "", "reason": f"llm_error:{trim(str(exc), 120)}"})
        parsed = self._selection_json(raw)
        if isinstance(parsed, dict):
            parsed = parsed.get("selected", parsed.get("selected_skills", parsed.get("skills", [])))
        if not isinstance(parsed, list):
            if raw is not None:
                result["fallback"] = result["fallback_type"] = "invalid_output"
            parsed = []
        seen: set[str] = set()
        for item in parsed:
            requested = item if isinstance(item, str) else (item.get("id", item.get("canonical_id", item.get("name", ""))) if isinstance(item, dict) else "")
            rationale = item.get("rationale", item.get("reason", "")) if isinstance(item, dict) else ""
            canonical = self.canonicalize_id(requested)
            cid = str(canonical.get("canonical_id", "")) if canonical.get("ok") else ""
            if not cid or cid not in candidate_ids:
                result["filtered"].append({"id": str(requested or ""), "reason": "not_in_candidates" if cid else canonical.get("code", "unknown")})
                continue
            if cid in seen:
                result["filtered"].append({"id": cid, "reason": "duplicate"})
                continue
            row = next((x for x in candidates if str(x.get("canonical_id", x.get("id", ""))) == cid), None)
            if not row:
                continue
            seen.add(cid)
            result["selected"].append({"id": cid, "canonical_id": cid, "name": row.get("name", cid), "rationale": trim(str(rationale or ""), 240)})
            if len(result["selected"]) >= max(1, min(3, int(limit or 3))):
                break
        # Apply declared conflict/dependency metadata after canonicalization.
        accepted: list[dict] = []
        accepted_ids: set[str] = set()
        accepted_names: set[str] = set()
        active_canonical_ids: list[str] = []
        for active in list(active_ids or []):
            resolved = self.canonicalize_id(active)
            if not resolved.get("ok"):
                continue
            active_id = str(resolved.get("canonical_id", "") or "")
            active_row = self.skills.get(active_id, {})
            active_canonical_ids.append(active_id)
            accepted_ids.add(active_id)
            accepted_names.add(str(active_row.get("name", active_id) or active_id))
        for selected in list(result["selected"]):
            cid = str(selected.get("id", "") or "")
            row = next((x for x in candidates if str(x.get("canonical_id", x.get("id", ""))) == cid), {})
            conflict_terms = {str(x).casefold() for x in row.get("conflicts", []) or []}
            conflict_hit = next((value for value in accepted_ids | accepted_names if value.casefold() in conflict_terms), "")
            if conflict_hit:
                resolved_conflict = self.canonicalize_id(conflict_hit)
                if resolved_conflict.get("ok"):
                    conflict_hit = str(resolved_conflict.get("canonical_id", conflict_hit))
            reverse_hit = ""
            if not conflict_hit:
                prior_rows = [
                    (str(previous.get("id", "")), next((x for x in candidates if str(x.get("canonical_id", x.get("id", ""))) == previous.get("id")), {}))
                    for previous in accepted
                ]
                prior_rows.extend(
                    (active_id, self._skill_metadata_record(active_id, self.skills.get(active_id, {})))
                    for active_id in active_canonical_ids
                )
                for previous_id, previous_row in prior_rows:
                    previous_conflicts = {str(x).casefold() for x in previous_row.get("conflicts", []) or []}
                    if cid.casefold() in previous_conflicts or str(row.get("name", "")).casefold() in previous_conflicts:
                        reverse_hit = previous_id
                        break
            if conflict_hit or reverse_hit:
                result["conflicts"].append({"id": cid, "with": conflict_hit or reverse_hit, "reason": "declared_conflict"})
                result["filtered"].append({"id": cid, "reason": "conflict"})
                continue
            accepted.append(selected)
            accepted_ids.add(cid)
            accepted_names.add(str(row.get("name", cid) or cid))
        result["selected"] = accepted
        selected_ids = {str(row.get("id", "")) for row in accepted} | accepted_ids
        selected_names = {str(row.get("name", "")) for row in accepted} | accepted_names
        dependency_valid: list[dict] = []
        for selected in accepted:
            cid = str(selected.get("id", "") or "")
            row = next((x for x in candidates if str(x.get("canonical_id", x.get("id", ""))) == cid), {})
            missing: list[str] = []
            for requirement in row.get("requires", []) or []:
                resolved = self.canonicalize_id(requirement)
                required_id = str(resolved.get("canonical_id", "")) if resolved.get("ok") else str(requirement)
                if required_id not in selected_ids and str(requirement) not in selected_names:
                    missing.append(required_id)
            if missing:
                result["requires"].append({"id": cid, "missing": missing})
                result["filtered"].append({"id": cid, "reason": "missing_dependency", "missing": missing})
                continue
            dependency_valid.append(selected)
        result["selected"] = dependency_valid
        # Local fallback is intentionally conservative: no selected metadata
        # means no body load, even for a large global catalog.
        if not result["selected"] and result["fallback_type"] == "none":
            result["fallback"] = result["fallback_type"] = "metadata"
        result["selection_order"] = [row["id"] for row in result["selected"]]
        result["duration_ms"] = int((time.monotonic() - started) * 1000)
        return result

    select_for_focus = select_skills

    def list_providers(self) -> list[dict]:
        out = []
        for provider in sorted(self.providers.values(), key=lambda x: x["provider_id"]):
            row = dict(provider)
            provider_id = str(row.get("provider_id", "") or "")
            row["root"] = self._public_provider_locator(str(row.get("root", "") or ""), provider_id)
            row["config_path"] = self._public_provider_locator(str(row.get("config_path", "") or ""), provider_id)
            out.append(row)
        return out

    def list_protocols(self) -> list[dict]:
        provider_counts: dict[str, int] = {}
        skill_counts: dict[str, int] = {}
        for p in self.providers.values():
            protocol = p.get("protocol", "")
            provider_counts[protocol] = provider_counts.get(protocol, 0) + 1
            skill_counts[protocol] = skill_counts.get(protocol, 0) + int(p.get("skill_count", 0))
        out = []
        for spec in SKILL_PROTOCOL_SPECS:
            protocol = spec["protocol"]
            out.append(
                {
                    "protocol": protocol,
                    "version": spec["version"],
                    "description": spec["description"],
                    "manifest_required": spec.get("manifest_required", []),
                    "manifest_optional": spec.get("manifest_optional", []),
                    "active_providers": provider_counts.get(protocol, 0),
                    "active_skills": skill_counts.get(protocol, 0),
                }
            )
        return out

    def protocol_examples(self) -> dict:
        return {
            "local_manifest": {
                "protocol": SKILL_PROTOCOL_LOCAL,
                "provider_id": "local-extra",
                "description": "Optional local provider mounted from a custom root",
                "root": "../extra-skills",
                "version": "1.0",
            },
            "clawhub_manifest": {
                "protocol": SKILL_PROTOCOL_CLAWHUB,
                "provider_id": "clawhub-default",
                "description": "Bridge to clawhub style skills",
                "root": "../clawhub",
                "version": "1.0",
                "skills": [
                    {
                        "name": "example-skill",
                        "file": "example/SKILL.md",
                        "description": "A clawhub mapped skill",
                        "attachments": ["example/references/*.md", "example/scripts/*.py"],
                    }
                ],
            },
            "http_manifest": {
                "protocol": SKILL_PROTOCOL_HTTP_JSON,
                "provider_id": "remote-catalog",
                "endpoint": "http://127.0.0.1:9000/skills.json",
                "description": "Remote backend skill catalog",
                "timeout": 4,
                "version": "1.0",
            },
            "placement": {
                "path": f"{SKILLS_VIRTUAL_PREFIX}/providers",
                "rule": "Drop provider JSON manifests under this folder; reload/list_skills will auto-detect them.",
            },
        }

    def _resolve_name(self, name: str) -> tuple[str | None, str | None]:
        target = (name or "").strip()
        if not target:
            return None, "Error: skill name required"
        resolved = self.canonicalize_id(target)
        if resolved.get("ok"):
            return str(resolved.get("canonical_id", "")), None
        if resolved.get("code") == "ambiguous":
            options = resolved.get("candidates", [])
            return None, f"Error: ambiguous skill '{target}'. use: {', '.join(sorted(str(x) for x in options))}"
        return None, f"Error: unknown skill '{target}'. available: {', '.join(self.list_names())}"

    def load(self, name: str) -> str:
        key, err = self._resolve_name(name)
        if err or not key:
            return err or "Error: skill not found"
        skill = self.skills[key]
        meta = skill.get("meta", {}) if isinstance(skill.get("meta"), dict) else {}
        skill_path = str(skill.get("skill_path", "") or "")
        skill_abs_path = str(skill.get("skill_abs_path", "") or "")
        body_text = str(skill.get("body", "") or "")
        runtime_contract = self._skill_runtime_contract(meta)
        compact_mode = bool(runtime_contract) and len(body_text) > SKILL_BODY_COMPACT_THRESHOLD_CHARS
        if compact_mode:
            body_render = (
                "[Clouds_Coder compact skill load]\n"
                "This skill has a long reference body. Follow the runtime contract and resource manifest first.\n"
                f"Full source remains available at: {skill_path or '(builtin)'}\n"
                "Use read_file on /skills/... entrypoints or the skill file itself only when the task needs deeper detail.\n\n"
                + trim(body_text, SKILL_BODY_PREVIEW_CHARS)
            )
        else:
            body_render = body_text
        lines = [
            (
                f"<skill name=\"{skill.get('name','')}\" "
                f"qualified_name=\"{key}\" "
                f"provider=\"{skill.get('provider_id','')}\" "
                f"protocol=\"{skill.get('protocol','')}\" "
                f"protocol_version=\"{skill.get('protocol_version','')}\" "
                f"path=\"{skill_path}\" "
                f"compact_mode=\"{'true' if compact_mode else 'false'}\">"
            ),
            body_render,
            "</skill>",
            "<skill_meta>",
            json_dumps(meta, indent=2),
            "</skill_meta>",
        ]
        if runtime_contract:
            lines.extend(
                [
                    "<skill_runtime_contract>",
                    runtime_contract,
                    "</skill_runtime_contract>",
                ]
            )
        attachments = skill.get("attachments", [])
        entrypoints = self._skill_entrypoints(meta)
        if entrypoints:
            lines.append("<skill_entrypoints>")
            att_map = {str(x.get("path", "")): x for x in attachments if isinstance(x, dict)}
            for rel in entrypoints:
                row = att_map.get(rel, {})
                try:
                    if not skill_abs_path:
                        raise ValueError("skill has no local absolute path")
                    base = Path(skill_abs_path).resolve().parent
                    virtual_path = self._public_provider_path(
                        str(skill.get("provider_id", "") or ""),
                        (base / rel).resolve(),
                    )
                except Exception:
                    virtual_path = str(row.get("virtual_path", "") or "")
                lines.append(
                    f"<entrypoint path=\"{rel}\" virtual_path=\"{virtual_path}\" />"
                )
            lines.append("</skill_entrypoints>")
        if attachments:
            lines.append("<skill_resources>")
            for item in sorted(
                attachments,
                key=lambda x: (
                    -int(x.get("priority", 0) or 0),
                    str(x.get("path", "")).lower(),
                ),
            )[:SKILL_RESOURCE_MANIFEST_MAX_ITEMS]:
                source_path, virtual_path = self._public_attachment_locator(item)
                lines.append(
                    f"<resource path=\"{item['path']}\" "
                    f"source=\"{source_path}\" "
                    f"virtual_path=\"{virtual_path}\" "
                    f"text=\"{'true' if item.get('text_available') else 'false'}\" "
                    f"size=\"{int(item.get('size', 0) or 0)}\" "
                    f"priority=\"{int(item.get('priority', 0) or 0)}\" />"
                )
            remaining = max(0, len(attachments) - SKILL_RESOURCE_MANIFEST_MAX_ITEMS)
            if remaining > 0:
                lines.append(f"<resource_omitted count=\"{remaining}\" />")
            lines.append("</skill_resources>")
            inline_attachments = self._inline_skill_attachments(attachments)
            if inline_attachments:
                lines.append("<skill_attachments>")
                for item in inline_attachments:
                    source_path, virtual_path = self._public_attachment_locator(item)
                    lines.append(
                        f"<file path=\"{item['path']}\" "
                        f"source=\"{source_path}\" "
                        f"virtual_path=\"{virtual_path}\" "
                        f"size=\"{int(item.get('size', 0) or 0)}\">"
                    )
                    lines.append(str(item.get("content", "") or ""))
                    lines.append("</file>")
                lines.append("</skill_attachments>")
        return "\n".join(lines)
